#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1'000'000'007;
const ll MOD1 = 998244353;
const int T = 14;

ll modPow(ll a, ll b, ll mod) {
    ll res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return res;
}

namespace linear_recurrence {
    vector<ll> berlekamp_massey(const vector<ll>& seq) {
        int n = seq.size();
        vector<ll> cur, ls;
        int lf = -1, ld = 0;
        for (int i = 0; i < n; ++i) {
            ll val = 0;
            for (int j = 0; j < (int)cur.size(); ++j)
                val = (val + seq[i - j - 1] * cur[j]) % MOD;
            val = (val - seq[i]) % MOD;
            if (val == 0) continue;
            if (cur.empty()) {
                cur.resize(i + 1, 0);
                lf = i;
                ld = val;
                continue;
            }
            ll k = (-val * modPow(ld, MOD - 2, MOD)) % MOD;
            vector<ll> c(i - lf - 1, 0);
            c.push_back(k);
            for (size_t j = 0; j < ls.size(); ++j)
                c.push_back((-ls[j] * k) % MOD);
            if (c.size() < cur.size()) c.resize(cur.size());
            for (size_t j = 0; j < cur.size(); ++j)
                c[j] = (c[j] + cur[j]) % MOD;
            if ((int)cur.size() < i - lf + (int)ls.size()) {
                ls = cur;
                lf = i;
                ld = val;
            }
            cur = c;
        }
        for (auto& x : cur) x = (x % MOD + MOD) % MOD;
        return cur;
    }

    vector<ll> h;
    vector<ll> a;
    int m;

    void multiply(vector<ll>& p, const vector<ll>& q) {
        vector<ll> tmp(m + m, 0);
        for (int i = 0; i < m; ++i) if (p[i])
            for (int j = 0; j < m; ++j)
                tmp[i + j] = (tmp[i + j] + p[i] * q[j]) % MOD;
        for (int i = m + m - 1; i >= m; --i) if (tmp[i])
            for (int j = m - 1; j >= 0; --j)
                tmp[i - j - 1] = (tmp[i - j - 1] + tmp[i] * h[j]) % MOD;
        for (int i = 0; i < m; ++i) p[i] = tmp[i];
    }

    ll compute(ll K) {
        vector<ll> s(m, 0), t(m, 0);
        s[0] = 1;
        if (m != 1) t[1] = 1;
        else t[0] = h[0];
        while (K) {
            if (K & 1) multiply(s, t);
            multiply(t, t);
            K >>= 1;
        }
        ll res = 0;
        for (int i = 0; i < m; ++i)
            res = (res + s[i] * a[i]) % MOD;
        return (res % MOD + MOD) % MOD;
    }

    ll solve(const vector<ll>& seq, ll n) {
        if (n < (ll)seq.size()) return seq[n];
        h = berlekamp_massey(seq);
        m = h.size();
        if (m == 0) return 0;
        for (int i = 0; i < m; ++i) {
            h[i] = h[i];
            a[i] = seq[i];
        }
        return compute(n);
    }
}

ll check(ll n, ll up) {
    ll cnt = 0;
    string st = to_string(n);
    int len = st.size();
    if (n > 0) cnt++;
    for (int i = 1; i < T; i++) {
        ll cur = 1, num = n;
        for (int j = 0; j + 1 < i; j++) cur *= 10;
        for (int j = len; j < i; j++) num *= 10;
        if (i < len) {
            string pref = st.substr(0, i);
            num = stoll(pref) + 1;
        }
        if (num > up) num = up;
        if (num > cur) cnt += num - cur;
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;
    n++;
    ll up = n;

    ll part = (n % MOD) * ((n / MOD1) + 2) % MOD;
    part = (MOD - part) % MOD;

    ll ans = 0;
    for (ll i = -n / MOD1 - 1; i <= n / MOD1 + 1; i++) {
        ll cur = 0;
        for (int j = 0; j < T; j++) {
            ll L = 0, R = 1;
            if (j >= 1) {
                L = 1;
                for (int k = 0; k + 1 < j; k++) L *= 10;
                R = L * 10;
            }
            if (R > n) R = n;
            ll lastR = R;
            if (L < R) {
                L--;
                while (R - L > 1) {
                    ll mid = (R + L) / 2;
                    if (check(mid, up) > mid + MOD1 * i - 1) R = mid;
                    else L = mid;
                }
                cur += lastR - R;
            }
        }
        ans += cur;
    }

    ans %= MOD;
    ans = ((-ans - part) % MOD * MOD1) % MOD;
    ans = (ans % MOD + MOD) % MOD;
    cout << ans << "\n";

    return 0;
}
